import {once} from 'node:events';
import type {AddressInfo} from 'node:net';
import {MongoClient} from 'mongodb';
import {WebSocket} from 'ws';
import {createHalEngine} from '../config.js';
import type {HalEngine, HalEngineConfig} from '../config.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from '../infrastructure/stores/mongo/mongoSessionStore.js';
import type {MongoSessionDocument} from '../infrastructure/stores/mongo/mongoSessionDocument.js';
import type {SessionListOptions, SessionStore} from '../types/sessionStore.js';
import type {Logger} from '../shared/logger.js';
import {setLogger} from '../shared/logger.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';

interface Row {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}
interface Frame {
  type: string;
  sessionId?: string;
  conversations?: Row[];
  code?: string;
  message?: string;
  timestamp?: number;
}

const engines: HalEngine[] = [];
const sockets: WebSocket[] = [];
const logs: Array<{level: string; message: string; fields?: Record<string, unknown>}> = [];
const logger = Object.fromEntries(
  ['debug', 'info', 'warn', 'error'].map(level => [
    level,
    (_category: string, message: string, fields?: Record<string, unknown>) => logs.push({level, message, fields}),
  ])
) as unknown as Logger;

// An observing decorator: every query still executes the shipped in-memory store.
class RecordedStore extends InMemorySessionStore {
  readonly calls: Array<{userId: string | number; options?: SessionListOptions}> = [];
  override listFor(userId: string | number, options?: SessionListOptions) {
    this.calls.push({userId, options});
    return super.listFor(userId, options);
  }
}

// A functioning legacy store port exposing only the five original operations.
function legacyPort(inner: InMemorySessionStore): SessionStore {
  return {
    create: inner.create.bind(inner),
    get: inner.get.bind(inner),
    delete: inner.delete.bind(inner),
    count: inner.count.bind(inner),
    clear: inner.clear.bind(inner),
  };
}

async function start(
  session: SessionStore,
  history?: {enabled: boolean},
  hooks?: NonNullable<HalEngineConfig['orchestrator']>['hooks']
) {
  const transport = {port: 0, resume: {enabled: true}, history};
  const engine = createHalEngine({
    provider: {type: 'bedrock', region: 'eu-central-1', modelId: 'unused', maxTokens: 1},
    prompt: {identity: 'History acceptance'},
    session,
    transport,
    auth: {ws: async () => ({id: 'owner'})},
    orchestrator: {hooks},
    logger,
  });
  engines.push(engine);
  await engine.start();
  return {engine, url: "'`ws://127.0.0.1:${(engine.server.address() as AddressInfo).port}/hal/ws`};
}

async function until(predicate: () => boolean) {
  const deadline = Date.now() + 1500;
  while (!predicate() && Date.now() < deadline) await new Promise(resolve => setTimeout(resolve, 5));
}

async function connect(url: string) {
  const ws = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'acceptance-credential']);
  sockets.push(ws);
  const frames: Frame[] = [];
  ws.on('message', raw => frames.push(JSON.parse(String(raw)) as Frame));
  await once(ws, 'open');
  await until(() => frames.some(frame => frame.type === 'connected'));
  expect(frames[0]?.type).toBe('connected');
  return {ws, frames};
}

async function request(client: Awaited<ReturnType<typeof connect>>, frame: unknown) {
  const offset = client.frames.length;
  client.ws.send(JSON.stringify(frame));
  await until(() => client.frames.slice(offset).some(item => ['error', 'conversation_list'].includes(item.type)));
  const timestamp = Date.now();
  client.ws.send(JSON.stringify({type: 'ping', timestamp}));
  await until(() => client.frames.slice(offset).some(item => item.type === 'pong' && item.timestamp === timestamp));
  return client.frames.slice(offset).filter(item => item.type "'!== '"'pong');
}

afterEach(async () => {
  for (const socket of sockets.splice(0)) socket.terminate();
  for (const engine of engines.splice(0)) await engine.stop();
  logs.length = 0;
  setLogger();
});

it('validates history limits and composite cursors independently of feature configuration', () => {
  const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'previous'};
  const valid = [{type: 'list_conversations'}, {type: 'list_conversations', limit: 1, before}, {type: 'list_conversations', limit: 200}];
  expect(valid.map(validateMessage)).toEqual(valid.map(data => ({valid: true, data})));
  for (const limit of [0, 201, 1.5, '10', null]) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
  }
  for (const cursor of ['not a date', before.updatedAt, null, {}, {updatedAt: before.updatedAt}, {sessionId: 'previous'}, {...before, updatedAt: 'not a date'}, {...before, sessionId: 123}]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
  }
  expect(validateMessage({type: 'list_conversations', userId: 'stranger'})).toEqual({valid: true, data: {type: 'list_conversations'}});
});

it('lists only the authenticated owner, pages tied activity, and resumes a listed conversation', async () => {
  const store = new RecordedStore();
  for (const id of ['a', 'b', 'foreign']) {
    store.create(id, id === 'foreign' ? 'stranger' : 'owner', {authHeaders: {authorization: 'private-credential'}}).entries.push({role: 'user', content: 'private-conversation', timestamp: '2099-01-01T00:00:00.000Z'});
  }
  const {url} = await start(store, {enabled: true});
  const client = await connect(url);
  const current = client.frames[0].sessionId;
  const expected = JSON.parse(JSON.stringify(InMemorySessionStore.prototype.listFor.call(store, 'owner'))) as Row[];
  expect(expected.map(row => row.sessionId)).toEqual(['b', 'a', current]);
  expect(client.frames.some(frame => frame.type === 'conversation_list')).toBe(false);
  const answer = await request(client, {type: 'list_conversations', userId: 'stranger'});
  expect(answer).toEqual([{type: 'conversation_list', conversations: expected}]);
  expect(store.calls).toEqual([{userId: 'owner', options: {limit: undefined, before: undefined}}]);
  for (const row of answer[0].conversations ?? []) {
    expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  let before: {updatedAt: string; sessionId: string} | undefined;
  const seen: Row[] = [];
  for (let page = 0; page < 4; page++) {
    const frames = await request(client, {type: 'list_conversations', limit: 1, before});
    expect(frames).toEqual([{type: 'conversation_list', conversations: expected.slice(page, page + 1)}]);
    expect(store.calls.at(-1)).toEqual({userId: 'owner', options: {limit: 1, before}});
    const row = frames[0].conversations?.[0];
    if (row) { seen.push(row); before = {updatedAt: row.updatedAt, sessionId: row.sessionId}; }
  }
  expect(seen).toEqual(expected);
  const resumed = await connect("'`${url}?sessionId=${seen[0].sessionId}`);
  resumed.ws.send(JSON.stringify({type: '"'ping', timestamp: 42}));
  await until(() => resumed.frames.some(frame => frame.type === 'pong'));
  expect(resumed.frames).toEqual([
    expect.objectContaining({type: 'connected', sessionId: 'b', resumed: true, entryCount: 1}),
    {type: 'entry_upsert', index: 0, entry: store.get('b')?.entries[0]},
    {type: 'pong', timestamp: 42},
  ]);
});

it('refuses disabled history and stores without listing with UNSUPPORTED, never an empty history', async () => {
  const inner = new InMemorySessionStore();
  inner.create('existing', 'owner');
  const outcomes = [];
  for (const [store, history] of [[inner, undefined], [inner, {enabled: false}], [legacyPort(inner), {enabled: true}]] as const) {
    const {url} = await start(store, history);
    const client = await connect(url);
    outcomes.push(await request(client, {type: 'list_conversations'}));
    expect(client.ws.readyState).toBe(WebSocket.OPEN);
  }
  expect(outcomes).toEqual(Array.from({length: 3}, () => [{type: 'error', code: 'UNSUPPORTED', message: expect.any(String)}]));
});

it('distinguishes an incapable collection from a failed store without leaking details or closing the socket', async () => {
  const driver = new MongoClient('mongodb://127.0.0.1:27017');
  const collection = driver.db('history_private_database').collection<MongoSessionDocument>('sessions');
  await driver.close();
  const withoutFind = {
    findOne: collection.findOne.bind(collection),
    updateOne: collection.updateOne.bind(collection),
    deleteOne: collection.deleteOne.bind(collection),
    deleteMany: collection.deleteMany.bind(collection),
    countDocuments: collection.countDocuments.bind(collection),
  };
  const outcomes = [];
  for (const [mongo, code] of [[new MongoSessionStore({collection: withoutFind}), 'UNSUPPORTED'], [new MongoSessionStore({collection}), 'SERVER_ERROR']] as const) {
    const inner = new InMemorySessionStore();
    const store = {...legacyPort(inner), listFor: mongo.listFor.bind(mongo)};
    const {url} = await start(store, {enabled: true});
    const client = await connect(url);
    const offset = logs.length;
    const frames = await request(client, {type: 'list_conversations'});
    outcomes.push({frames, code});
    expect(client.ws.readyState).toBe(WebSocket.OPEN);
    if (code === 'SERVER_ERROR') {
      expect(logs.slice(offset)).toEqual(expect.arrayContaining([expect.objectContaining({level: 'error', fields: expect.objectContaining({sessionId: client.frames[0].sessionId})})]));
    }
    expect(JSON.stringify({frames, logs: logs.slice(offset)})).not.toMatch(/history_private_database|acceptance-credential/);
  }
  expect(outcomes).toEqual(['UNSUPPORTED', 'SERVER_ERROR'].map(code => ({code, frames: [{type: 'error', code, message: expect.any(String)}]})));
  expect(outcomes[1].frames[0].message).not.toMatch(/Mongo|closed|connect|topology/i);
});

it('answers history while the real streaming turn holds the session lock', async () => {
  let release = () => {};
  const held = new Promise<void>(resolve => { release = resolve; });
  let entered = false;
  const {url, engine} = await start(new InMemorySessionStore(), {enabled: true}, {
    beforeModelResponse: async (_session, prompt) => { entered = true; await held; return prompt; },
  });
  const client = await connect(url);
  client.ws.send(JSON.stringify({type: 'user_message', content: 'hold this turn'}));
  await until(() => entered);
  expect(entered).toBe(true);
  try {
    const frames = await request(client, {type: 'list_conversations'});
    expect(frames).toEqual([{type: 'conversation_list', conversations: [expect.objectContaining({sessionId: client.frames[0].sessionId, entryCount: 1})]}]);
    expect(client.frames.some(frame => frame.type === 'stream_end')).toBe(false);
  } finally {
    const serverSocket = [...engine.wss.clients][0];
    const closed = once(serverSocket, 'close');
    client.ws.terminate();
    await closed;
    release();
  }
});
